import { helper } from '@ember/component/helper';

/** When displaying a number in a hbs template, limit the number of decimal places.
 * Implemented by wraping the standard JavaScript method Number.prototype.toFixed().
 * @return number, with the specified number of decimal places.
 * Return the original value unmodified if not a number.
 */
export function numberToFixed(params) {
  /** Generated by Gemini. */
  let value = params[0];
  let decimals = params[1] !== undefined ? params[1] : 2; // Default to 2 decimals

  if (typeof value === 'number' && !isNaN(value)) {
    return value.toFixed(decimals);
  }
  return value; // Return original value or a default if not a number
}

export default helper(numberToFixed);
